import heapq


def k_smallest_numbers(numbers, k):
    """Return a list of the k smallest values from numbers, in ascending order.

    Duplicates count separately. If there are fewer than k items, all items
    are returned, sorted. Raises ValueError if k is negative.
    """
    if k < 0:
        raise ValueError("k must be a non-negative integer")
    if k == 0:
        return []
    return heapq.nsmallest(k, numbers)

