import heapq


def k_smallest_numbers(numbers, k):
    """Return a list of the k smallest values from numbers, in ascending order.

    Duplicates count separately. If there are fewer than k items, all of them
    are returned, sorted.
    """
    if k <= 0:
        return []
    items = list(numbers)
    if k >= len(items):
        return sorted(items)
    return heapq.nsmallest(k, items)

