from fractions import Fraction


def sort_groups_by_mean(groups):
    """Return (key, values) tuples sorted by the mean of values, highest first.

    Means are computed exactly using Fraction, so very large integers compare
    correctly. Ties keep the dict's original insertion order because sorted()
    is stable, and reverse=True preserves that stability.
    """
    def mean(item):
        values = item[1]
        return Fraction(sum(values), len(values))

    return sorted(groups.items(), key=mean, reverse=True)

