import json


def _hashable(value):
    """Return a hashable representation of a JSON value."""
    try:
        hash(value)
        return value
    except TypeError:
        # Lists and dicts cannot be dict keys, so use a canonical JSON string.
        return json.dumps(value, sort_keys=True)


def count_key_values(json_documents, key):
    counts = {}
    for doc in json_documents:
        data = json.loads(doc)
        if not isinstance(data, dict) or key not in data:
            continue
        value = _hashable(data[key])
        counts[value] = counts.get(value, 0) + 1
    return counts

