        csv_text = csv_text[1:]
    reader = csv.reader(io.StringIO(csv_text, newline=''))
    header = None
    for row in reader:
        if row and any(cell.strip() for cell in row):
            header = [h.strip().lower() for h in row]
            break
    if header is None:
        raise ValueError("missing header")
    if 'product' not in header or 'quantity' not in header:
        raise ValueError("header must contain 'product' and 'quantity' columns")
    p_idx = header.index('product')
    q_idx = header.index('quantity')

    totals = {}
    for row in reader:
        if not row or not any(cell.strip() for cell in row):
            continue
        if len(row) <= max(p_idx, q_idx):
            raise ValueError("row has missing fields: %r" % (row,))
        product = row[p_idx].strip()
        qty_text = row[q_idx].strip()
        if not _INT_RE.fullmatch(qty_text):
            raise ValueError("invalid quantity: %r" % (row[q_idx],))
        qty = int(qty_text)
        if product not in totals:
            totals[product] = 0
        totals[product] += qty

    if not totals:
        raise ValueError("no data rows")

    best_product = None
    best_total = None
    for product, total in totals.items():
        if best_total is None or total > best_total:
            best_product = product
            best_total = total
    return best_product

