_PUNCT_TABLE = str.maketrans('', '', string.punctuation)


def count_non_stopwords(sentence, stopwords):
    if not sentence:
        return 0
    stop_set = {s.lower() for s in stopwords}
    words = []
    for token in sentence.split():
        cleaned = token.translate(_PUNCT_TABLE).lower()
        if cleaned:
            words.append(cleaned)
    if not words:
        return 0
    words = words[:-1]
    return sum(1 for w in words if w not in stop_set)

