import re


def count_non_stopwords(sentence, stopwords):
    """Count words in the sentence that are not stopwords, excluding the last word.

    Punctuation is ignored and comparison is case-insensitive.
    """
    if not sentence:
        return 0
    stop_set = {str(w).lower() for w in (stopwords or [])}
    words = []
    for token in sentence.split():
        cleaned = re.sub(r"[^\w]|_", "", token).lower()
        if cleaned:
            words.append(cleaned)
    return sum(1 for w in words[:-1] if w not in stop_set)

