def max_weight_substring(text, weights):
    if not text:
        return ''
    best_sum = None
    best_start = 0
    best_end = 0
    cur_sum = 0
    cur_start = 0
    for i, ch in enumerate(text):
        w = weights.get(ch, 0)
        if i == 0 or cur_sum <= 0:
            cur_sum = w
            cur_start = i
        else:
            cur_sum += w
        if best_sum is None or cur_sum > best_sum:
            best_sum = cur_sum
            best_start = cur_start
            best_end = i + 1
    return text[best_start:best_end]

import itertools
import math


def permutation_factorial_sums(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list of integers")
    for n in numbers:
        if isinstance(n, bool) or not isinstance(n, int):
            raise TypeError("numbers must be a list of integers")
    for n in numbers:
        if n < 0:
            raise ValueError("numbers must be non-negative")
    if not numbers:
        return ([], [])
    perms = list(itertools.permutations(numbers))
    fact_cache = {}

    def fact(n):
        if n not in fact_cache:
            fact_cache[n] = math.factorial(n)
        return fact_cache[n]

    sums = [sum(fact(x) for x in p) for p in perms]
    return (sums, perms)

