        return [], b''

    n = len(header)
    rows = []
    norm_rows = []
    for rec in raw_rows:
        vals = list(rec[:n]) + [''] * (n - len(rec))
        norm_rows.append(vals)
        rows.append({h: v for h, v in zip(header, vals)})

    out = io.StringIO(newline='')
    writer = csv.writer(out, delimiter=delimiter, lineterminator='\n')
    writer.writerow(header)
    for vals in norm_rows:
        writer.writerow(vals)
    converted = out.getvalue().encode(to_encoding)
    return rows, converted

