def parse_dict_lines(texts):
    """Parse a list of file contents where each non-blank line is a Python dict literal."""
    result = []
    for file_index, text in enumerate(texts):
        if not isinstance(text, str):
            raise ValueError("File contents at index %d is not a string" % file_index)
        for line_no, raw_line in enumerate(text.split("\n"), start=1):
            line = raw_line.rstrip("\r").strip()
