                    % (file_index, line_no, raw_line)
                ) from exc
            if not isinstance(tree.body, ast.Dict):
                raise ValueError(
                    "File %d, line %d: not a dictionary literal: %r"
                    % (file_index, line_no, raw_line)
                )
            try:
                value = ast.literal_eval(tree)
            except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError) as exc:
                raise ValueError(
                    "File %d, line %d: not a valid dictionary literal: %r"
                    % (file_index, line_no, raw_line)
                ) from exc
            if not isinstance(value, dict):
                raise ValueError(
                    "File %d, line %d: not a dictionary literal: %r"
                    % (file_index, line_no, raw_line)
                )
            result.append(value)
    return result

