import ast


def parse_dict_lines(texts):
    """Parse a list of file contents where each non-blank line is a dict literal.

    Returns the dictionaries in order (file by file, line by line).
    Raises ValueError if any non-blank line is not a valid dictionary literal.
    Whitespace-only lines (e.g. a trailing newline) are ignored.
    """
    results = []
    for file_index, text in enumerate(texts):
        if not isinstance(text, str):
            raise ValueError(
                f"File {file_index}: expected a string, got {type(text).__name__}"
            )
        for line_no, line in enumerate(text.splitlines(), start=1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                value = ast.literal_eval(stripped)
            except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError) as exc:
                raise ValueError(
                    f"File {file_index}, line {line_no}: invalid literal: {line!r}"
                ) from exc
            if not isinstance(value, dict):
                raise ValueError(
                    f"File {file_index}, line {line_no}: not a dictionary literal: {line!r}"
                )
            results.append(value)
    return results

