import re
from urllib.parse import unquote

_OK_TEMPLATE = "HTTP/1.1 200 OK\r\nContent-Length: {n}\r\n\r\n{content}"
_NOT_FOUND = "HTTP/1.1 404 NOT FOUND\r\n\r\nFile Not Found"
_BAD_REQUEST = "HTTP/1.1 400 BAD REQUEST\r\n\r\nBad Request"
_VERSION_RE = re.compile(r"^HTTP/\d+(\.\d+)?$")


def _ok(content):
    content = str(content)
    return _OK_TEMPLATE.format(n=len(content.encode("utf-8")), content=content)


def serve_static_file(request, files):
    if isinstance(request, bytes):
        try:
            request = request.decode("utf-8")
        except UnicodeDecodeError:
            return _BAD_REQUEST
    if not isinstance(request, str):
        return _BAD_REQUEST
    lines = request.splitlines()
    if not lines:
        return _BAD_REQUEST
    first = lines[0].strip()
    parts = first.split()
    if len(parts) != 3:
        return _BAD_REQUEST
    method, path, version = parts
    if method != "GET" or not path.startswith("/") or not _VERSION_RE.match(version):
        return _BAD_REQUEST
    if files is None:
        files = {}
    name = path[1:]
    candidates = [name]
    base = name.split("?", 1)[0].split("#", 1)[0]
    if base not in candidates:
        candidates.append(base)
    for c in list(candidates):
        u = unquote(c)
        if u not in candidates:
            candidates.append(u)
