    line = request.split("\n", 1)[0].rstrip("\r")
    parts = line.split(" ")
    if len(parts) != 3:
        return _BAD
    method, path, version = parts
    if method != "GET" or not path.startswith("/") or not _VERSION_RE.match(version):
        return _BAD
