def _find_matching_brace(text, start):
    """Return the index of the '}' that closes the '{' at text[start],
    respecting Python string literals. Return None if not found."""
    n = len(text)
    depth = 0
    i = start
    while i < n:
        c = text[i]
        if c in ('"', "'"):
            if text.startswith(c * 3, i):
                q = c * 3
                j = i + 3
                while j < n:
                    if text[j] == '\\':
                        j += 2
                        continue
                    if text.startswith(q, j):
                        break
                    j += 1
                else:
                    return None
                if j >= n:
                    return None
                i = j + 3
                continue
            else:
                j = i + 1
                while j < n:
                    ch = text[j]
                    if ch == '\\':
                        j += 2
                        continue
                    if ch == c:
                        break
                    if ch == '\n':
                        return None
                    j += 1
                else:
                    return None
                if j >= n:
                    return None
                i = j + 1
                continue
        elif c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def extract_dicts(text):
    """Find all outermost Python dict literals in text and return them as dicts."""
    if not isinstance(text, str):
        return []
    results = []
    n = len(text)
    i = 0
    while i < n:
        if text[i] != '{':
            i += 1
            continue
        end = _find_matching_brace(text, i)
        if end is not None:
            segment = text[i:end + 1]
            try:
                value = ast.literal_eval(segment)
            except Exception:
                value = None
            if isinstance(value, dict):
                results.append(value)
                i = end + 1
                continue
        i += 1
    return results

