from collections import Counter


def _rows(csv_text, delimiter):
    if isinstance(delimiter, str) and len(delimiter) == 1:
        reader = csv.reader(io.StringIO(csv_text, newline=''), delimiter=delimiter)
        for row in reader:
            yield row
    else:
        for line in csv_text.splitlines():
            yield line.split(delimiter) if delimiter else [line]


def most_common_csv_words(csv_text, delimiter):
    counts = Counter()
    for row in _rows(csv_text, delimiter):
        for cell in row:
            word = cell.strip()
            if word:
                counts[word] += 1
    # Counter preserves first-insertion order; sorted is stable, so ties keep first-occurrence order
    return sorted(counts.items(), key=lambda kv: -kv[1])

