import base64
import hashlib


def hash_password_with_salt(password, salt, iterations):
    """Hash a password with PBKDF2-HMAC-SHA256 into a 32-byte key.

    Returns (base64(salt), base64(derived_key)), both as bytes.
    Raises ValueError if the password is None or empty.
    """
    if password is None or len(password) == 0:
        raise ValueError("Password must not be None or empty")

    if isinstance(password, str):
        password_bytes = password.encode("utf-8")
    elif isinstance(password, (bytes, bytearray, memoryview)):
        password_bytes = bytes(password)
    else:
        raise TypeError("password must be a str")

    if isinstance(salt, str):
        salt_bytes = salt.encode("utf-8")
    elif isinstance(salt, (bytes, bytearray, memoryview)):
        salt_bytes = bytes(salt)
    else:
        raise TypeError("salt must be bytes")

    if isinstance(iterations, bool) or not isinstance(iterations, int):
        raise TypeError("iterations must be an int")
    if iterations < 1:
        raise ValueError("iterations must be a positive integer")

    derived_key = hashlib.pbkdf2_hmac("sha256", password_bytes, salt_bytes, iterations, dklen=32)

    return base64.b64encode(salt_bytes), base64.b64encode(derived_key)

