def count_subset_sums(elements, subset_size):
    elements = tuple(elements)
    n = len(elements)
    k = subset_size
    if not isinstance(k, int) or k < 0 or k > n:
        return {}
    dp = [Counter() for _ in range(k + 1)]
    dp[0][0] = 1
    for i, x in enumerate(elements):
        upper = min(k, i + 1)
        for j in range(upper, 0, -1):
            prev = dp[j - 1]
            if not prev:
