def group_files_by_extension(filenames):
    """Group filenames by extension (everything after the first dot).

    Files without a dot, or whose extension would be empty (e.g. 'file.'),
    have no subfolder to go into, so they are left out of the result.
    """
    groups = {}
    for name in filenames:
        if '.' not in name:
            continue
        ext = name.split('.', 1)[1]
        if not ext:
            # An empty extension cannot name a subfolder; the file stays put.
            continue
        groups.setdefault(ext, []).append(name)
    return groups

