def closest_pair(points):
    n = len(points)
    if n < 2:
        return None

    # Handle exact duplicates: distance 0 is minimal; choose the smallest (i, j).
    first = {}
    dup_best = None
    for j, p in enumerate(points):
        key = (p[0], p[1])
        if key in first:
            cand = (first[key], j)
            if dup_best is None or cand < dup_best:
                dup_best = cand
        else:
            first[key] = j
    if dup_best is not None:
        i, j = dup_best
        return (points[i], points[j])

    def make_key(a, b):
        pa = points[a]
        pb = points[b]
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        d2 = dx * dx + dy * dy
        if a < b:
            return (d2, a, b)
        return (d2, b, a)

    px = sorted(range(n), key=lambda k: (points[k][0], points[k][1]))

    def rec(lo, hi):
        if hi - lo <= 3:
            best = None
            for a in range(lo, hi):
                for b in range(a + 1, hi):
                    k = make_key(px[a], px[b])
                    if best is None or k < best:
                        best = k
            ys = sorted(px[lo:hi], key=lambda k: points[k][1])
            return ys, best
        mid = (lo + hi) // 2
        midx = points[px[mid]][0]
        ly, lb = rec(lo, mid)
        ry, rb = rec(mid, hi)
        if lb is None:
            best = rb
        elif rb is None:
            best = lb
        else:
            best = lb if lb < rb else rb
        # merge by y
        merged = []
        i = j = 0
        while i < len(ly) and j < len(ry):
            if points[ly[i]][1] <= points[ry[j]][1]:
                merged.append(ly[i])
                i += 1
            else:
                merged.append(ry[j])
                j += 1
        merged.extend(ly[i:])
        merged.extend(ry[j:])
        d2 = best[0]
        strip = []
        for k in merged:
            dx = points[k][0] - midx
            if dx * dx <= d2:
                strip.append(k)
        m = len(strip)
        for a in range(m):
            ya = points[strip[a]][1]
            for b in range(a + 1, m):
                dy = points[strip[b]][1] - ya
                if dy * dy > best[0]:
                    break
                k = make_key(strip[a], strip[b])
                if k < best:
                    best = k
        return merged, best

    _, best = rec(0, n)
    _, i, j = best
    return (points[i], points[j])

