    order = sorted(range(n), key=lambda i: (pts[i][0], pts[i][1]))
    best = None  # (d2, i, j) with i < j
    active = []  # sorted list of (y, idx)
    left = 0
    for k in order:
        x, y = pts[k]
        if best is not None:
            while left < n:
                idx = order[left]
                if idx == k:
                    break
                dx = x - pts[idx][0]
                if dx * dx > best[0]:
                    item = (pts[idx][1], idx)
                    pos = bisect_left(active, item)
                    if pos < len(active) and active[pos] == item:
                        active.pop(pos)
                    left += 1
                else:
                    break
        if best is None:
            lo, hi = 0, len(active)
        else:
            r = math.sqrt(best[0])
            margin = r * 1e-9 + abs(y) * 1e-12 + 1e-12
            lo = bisect_left(active, (y - r - margin, -1))
            hi = bisect_right(active, (y + r + margin, n + 1))
        for t in range(lo, hi):
            yy, j = active[t]
            dx = x - pts[j][0]
            dy = y - yy
            d2 = dx * dx + dy * dy
            key = (d2, j, k) if j < k else (d2, k, j)
            if best is None or key < best:
                best = key
        insort(active, (y, k))
    return (pts[best[1]], pts[best[2]])

