def decode_base64_json_values(json_text):
    """Decode a JSON object whose values are base64-encoded UTF-8 strings.

    Returns a dict mapping each key to its decoded, NFC-normalized text.
    Raises ValueError for invalid JSON, a non-object top level, non-string
    values, invalid base64, or decoded bytes that are not valid UTF-8.
    """
    if isinstance(json_text, (bytes, bytearray)):
        try:
            json_text = json_text.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("Input is not valid UTF-8 text") from exc
    if not isinstance(json_text, str):
        raise ValueError("Input must be a JSON string")

    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON top-level value must be an object")

    result = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} is not a string")
        try:
            raw = base64.b64decode(value.encode("ascii"), validate=True)
        except (binascii.Error, UnicodeEncodeError, ValueError) as exc:
            raise ValueError(f"Value for key {key!r} is not valid base64") from exc
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(
                f"Decoded value for key {key!r} is not valid UTF-8"
            ) from exc
        result[key] = unicodedata.normalize("NFC", text)

    return result

