import math
import struct

_MASK = 0xFFFFFFFF
_S = [7, 12, 17, 22] * 4 + [5, 9, 14, 20] * 4 + [4, 11, 16, 23] * 4 + [6, 10, 15, 21] * 4
_K = [int(abs(math.sin(i + 1)) * 4294967296) & _MASK for i in range(64)]


def _rotl(x, c):
    x &= _MASK
    return ((x << c) | (x >> (32 - c))) & _MASK


def _pure_md5_hex(data):
    a0, b0, c0, d0 = 0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476
    bitlen = (len(data) * 8) & 0xFFFFFFFFFFFFFFFF
    msg = data + b'\x80'
    msg += b'\x00' * ((56 - len(msg) % 64) % 64)
    msg += struct.pack('<Q', bitlen)
    for off in range(0, len(msg), 64):
        m = struct.unpack('<16I', msg[off:off + 64])
        a, b, c, d = a0, b0, c0, d0
        for i in range(64):
            if i < 16:
                f = (b & c) | (~b & d)
                g = i
            elif i < 32:
                f = (d & b) | (~d & c)
                g = (5 * i + 1) % 16
            elif i < 48:
                f = b ^ c ^ d
                g = (3 * i + 5) % 16
            else:
                f = c ^ (b | (~d & _MASK))
                g = (7 * i) % 16
            f = (f + a + _K[i] + m[g]) & _MASK
            a, d, c = d, c, b
            b = (b + _rotl(f, _S[i])) & _MASK
        a0 = (a0 + a) & _MASK
        b0 = (b0 + b) & _MASK
        c0 = (c0 + c) & _MASK
        d0 = (d0 + d) & _MASK
    return struct.pack('<4I', a0, b0, c0, d0).hex()


def _md5_hex(data):
    try:
        try:
            h = hashlib.md5(usedforsecurity=False)
        except TypeError:
            h = hashlib.md5()
        h.update(data)
        return h.hexdigest().lower()
    except (ValueError, AttributeError):
        return _pure_md5_hex(data)


def md5_and_sha256_hex(data):
    if isinstance(data, str):
        raise TypeError('data must be bytes-like, not str')
    data = bytes(data)
    md5_hex = _md5_hex(data)
    sha256_hex = hashlib.sha256(data).hexdigest().lower()
    return (md5_hex, sha256_hex)

