    # Tie-break: choose the first pair (i < j) in dict order achieving best,
    # matching a brute-force scan over all pairs.
    suffix_max = [float('-inf')] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_max[i] = max(cs[i], suffix_max[i + 1])

    for i in range(n - 1):
        m = suffix_max[i + 1]
        if cs[i] + m == best:
            for j in range(i + 1, n):
                if cs[i] + cs[j] == best:
                    return (keys[i], keys[j])

    return (keys[a], keys[b])

