import heapq


def top_three_letters(counts):
    """Return up to 3 letters with the highest counts, highest first.

    Ties are broken by insertion order of the dict (earlier first).
    """
    if not counts:
        return []
    # heapq.nlargest is stable with respect to input order for equal keys
    return heapq.nlargest(3, counts, key=counts.__getitem__)

