import html
import re


def _wrap_line(line, line_length):
    words = [w for w in line.split(' ') if w != '']
    if not words:
        return ['']
    lines = []
    current = words[0]
    for word in words[1:]:
        if len(current) + 1 + len(word) <= line_length:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines


def clean_and_wrap(encoded, line_length):
    if isinstance(encoded, str):
        encoded = encoded.strip().encode('ascii')
    raw = base64.b64decode(encoded)
    text = raw.decode('utf-8')
    text = html.unescape(text)
    text = re.sub(' +', ' ', text)
    text = text.strip(' ')
    if text == '':
        return ''
    out = []
    for line in text.split('\n'):
        out.extend(_wrap_line(line, line_length))
    return '\n'.join(out)

