    words = text.split(' ')
    lines = []
    current = ''
    for word in words:
        # Break words that are longer than the line length on their own
        while len(word) > line_length:
            if current:
                lines.append(current)
                current = ''
            lines.append(word[:line_length])
            word = word[line_length:]
        if not word:
            continue
        if not current:
