import math


def letter_value_product(letters):
    """Return the product of letter values where A=1, B=2, ..., Z=26.

    An empty list returns 1 (the empty product).
    """
    values = []
    for ch in letters:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"Invalid letter: {ch!r}")
        c = ch.upper()
        if not ('A' <= c <= 'Z'):
            raise ValueError(f"Invalid letter: {ch!r}")
        values.append(ord(c) - ord('A') + 1)
    return int(math.prod(values))

