import hmac


def hash_or_verify_sha256(text, expected=None):
    """Return the SHA-256 hex digest of text, or verify it against expected.

    If expected is None, return the lowercase hexadecimal SHA-256 digest of
    text (UTF-8 encoded). Otherwise, return True if expected exactly equals
    that digest, and False if it does not.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string, not %s" % type(text).__name__)
    if expected is not None and not isinstance(expected, str):
        raise TypeError(
            "expected must be a string or None, not %s" % type(expected).__name__
        )

    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()

    if expected is None:
        return digest

    # Constant-time comparison; encode to bytes so that non-ASCII input
    # does not raise inside compare_digest.
    try:
        expected_bytes = expected.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return hmac.compare_digest(expected_bytes, digest.encode("ascii"))

