def decode_hex_text(hex_string):
    """Convert a hex string to bytes and decode as UTF-8, dropping invalid bytes.

    Raises ValueError if the input is not a valid hex string.
    """
    if isinstance(hex_string, (bytes, bytearray)):
        try:
            hex_string = hex_string.decode('ascii')
        except UnicodeDecodeError:
            raise ValueError('Input contains non-hex characters')
    if not isinstance(hex_string, str):
        raise ValueError('Input must be a string of hexadecimal digits')
    if len(hex_string) % 2 != 0:
        raise ValueError('Hex string must have an even number of digits')
    valid = set('0123456789abcdefABCDEF')
    for ch in hex_string:
        if ch not in valid:
            raise ValueError('Input contains non-hex characters: %r' % ch)
    try:
        data = binascii.unhexlify(hex_string)
    except (binascii.Error, TypeError) as exc:
        raise ValueError('Invalid hex string: %s' % exc)
    return data.decode('utf-8', errors='ignore')

