def decode_hex_query_param(url):
    """Decode the hex-encoded 'q' query parameter of a URL as UTF-8 text.

    Returns None if 'q' is missing, is not valid hex, or does not decode as UTF-8.
    If 'q' appears more than once, the first value is used.
