import re


def count_documents_containing_word(documents, word):
    """Return how many documents contain `word` as a whole word, case-insensitively.

    A match counts only if it is not directly preceded or followed by a word
    character (letter, digit or underscore), so punctuation next to the word is
    fine but a longer word containing it (e.g. 'apples' for 'apple') is not.
    """
    if not word:
        return 0
    pattern = re.compile(r'(?<!\w)' + re.escape(word) + r'(?!\w)', re.IGNORECASE)
    count = 0
    for doc in documents:
        if doc is None:
            continue
        if not isinstance(doc, str):
            doc = str(doc)
        if pattern.search(doc):
            count += 1
    return count

