import math


def sum_log_combination_products(numbers):
    nums = list(numbers)
    for x in nums:
        if x <= 0:
            raise ValueError("All numbers must be positive")
    n = len(nums)
    if n == 0:
        return 0.0
    # Each element appears in exactly 2**(n-1) of the non-empty combinations,
    # and log(product) = sum of logs.
    total_log = math.fsum(math.log(x) for x in nums)
    return float(total_log * (2 ** (n - 1)))

