import math


def count_letters_in_combinations(letters, n):
    """Return a dict mapping each letter to the number of n-letter
    combinations (order doesn't matter, no repetition) it appears in."""
    total = len(letters)
    if n < 1 or n > total:
        count = 0
    else:
        # Fix the letter, then choose the remaining n-1 from the other total-1.
        count = math.comb(total - 1, n - 1)
    return {letter: count for letter in letters}

