def _find_matching_brace(text, start):
    """Return the index of the '}' matching the '{' at text[start], honouring
    Python string literals. Return None if no match is found."""
    n = len(text)
    depth = 0
    i = start
    while i < n:
        c = text[i]
        if c == '"' or c == "'":
            q = c * 3 if text.startswith(c * 3, i) else c
            i += len(q)
            closed = False
            while i < n:
                ch = text[i]
                if ch == '\\':
                    i += 2
                    continue
                if text.startswith(q, i):
                    i += len(q)
                    closed = True
                    break
                if len(q) == 1 and ch == '\n':
                    return None
                i += 1
            if not closed:
                return None
            continue
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def _try_eval(src):
    try:
        return True, ast.literal_eval(src)
    except Exception:
        return False, None


