from collections import Counter


def count_urls_in_json(json_str, top_n=10):
    """Count URL string values (starting with http://, https:// or www.) in a JSON
    document, including nested objects and arrays. Returns a dict of the top_n
    most frequent URLs mapped to their counts."""
    if isinstance(json_str, (bytes, bytearray)):
        try:
            json_str = json_str.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ValueError("Invalid JSON string") from e
    if not isinstance(json_str, str):
        raise ValueError("Invalid JSON string")
    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, TypeError) as e:
        raise ValueError("Invalid JSON string") from e

    prefixes = ("http://", "https://", "www.")
    counts = Counter()
    first_seen = {}

    stack = [data]
    order = 0
    # Iterative depth-first traversal preserving document order
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            stack.extend(reversed(list(item.values())))
        elif isinstance(item, list):
            stack.extend(reversed(item))
        elif isinstance(item, str):
            if item.startswith(prefixes):
                counts[item] += 1
                if item not in first_seen:
                    first_seen[item] = order
                    order += 1

    if top_n is None:
        selected = list(counts)
    else:
        try:
            n = int(top_n)
        except (TypeError, ValueError):
            n = 10
        if n <= 0:
            return {}
        # Sort by descending count, ties broken by first appearance
        ranked = sorted(counts, key=lambda u: (-counts[u], first_seen[u]))
        selected = ranked[:n]

    # Return in order of first appearance in the document
    selected.sort(key=lambda u: first_seen[u])
    return {u: counts[u] for u in selected}

