def _int_distribution(elements, k):
    # Count how many subsets of size k give each sum, without listing them all.
    dp = [Counter() for _ in range(k + 1)]
    dp[0][0] = 1
    for i, x in enumerate(elements):
        for j in range(min(i + 1, k), 0, -1):
            prev = dp[j - 1]
            if not prev:
                continue
            cur = dp[j]
            for s, c in prev.items():
                cur[s + x] += c
    return dp[k]


def subset_sum_stats(elements, subset_size):
    elements = tuple(elements)
    k = subset_size
    if k < 0 or k > len(elements):
        raise ValueError("no subsets of the requested size")

    if all(isinstance(e, Integral) for e in elements):
        dist = _int_distribution([int(e) for e in elements], k)
    else:
        dist = Counter(sum(c) for c in combinations(elements, k))

    total = sum(dist.values())
    if total == 0:
        raise ValueError("no subsets of the requested size")

    mean = sum(s * c for s, c in dist.items()) / total

    keys = sorted(dist)
    lo_idx = (total - 1) // 2
    hi_idx = total // 2
    lo_val = hi_val = None
    cum = 0
    for s in keys:
        cum += dist[s]
        if lo_val is None and cum > lo_idx:
            lo_val = s
        if cum > hi_idx:
            hi_val = s
            break
    median = (lo_val + hi_val) / 2

    best = max(dist.values())
    mode = min(s for s, c in dist.items() if c == best)

    return {'mean': float(mean), 'median': float(median), 'mode': mode}

