            best = None
            for a in range(lo, hi):
                for b in range(a + 1, hi):
                    k = key(P[a], P[b])
                    if best is None or k < best:
                        best = k
            ys = sorted(P[lo:hi], key=lambda t: t[1])
            return best, ys
        mid = (lo + hi) // 2
        midx = P[mid][0]
        bl, yl = rec(lo, mid)
        br, yr = rec(mid, hi)
        best = bl if bl < br else br
        merged = list(heapq.merge(yl, yr, key=lambda t: t[1]))
