def remove_matching_rows(rows, to_remove):
    targets = [tuple(t) for t in to_remove]
    hashable = set()
    unhashable = []
    for t in targets:
        try:
            hashable.add(t)
        except TypeError:
            unhashable.append(t)

    def matches(row):
        key = tuple(row)
        try:
            if key in hashable:
                return True
        except TypeError:
            for t in targets:
                if t == key:
                    return True
            return False
        for t in unhashable:
            if t == key:
                return True
        return False

    return [list(row) for row in rows if not matches(row)]

