import re


def count_documents_containing_word(documents, word):
    """Return how many documents contain `word` as a whole word, ignoring case.

    Punctuation next to the word does not prevent a match, but the word as part
    of a longer word (e.g. 'apple' in 'apples') does not count.
    """
    if documents is None or word is None:
        return 0
    word = str(word).strip()
    if not word:
        return 0
    pattern = re.compile(r'(?<!\w)' + re.escape(word) + r'(?!\w)', re.IGNORECASE)
    count = 0
    for doc in documents:
        if doc is None:
            continue
        if not isinstance(doc, str):
            doc = str(doc)
        if pattern.search(doc):
            count += 1
    return count

