import io
import json


class _RawNumber(str):
    """Marks a JSON number so its original text is kept exactly."""
    pass


def _cell(value):
    if isinstance(value, str):
        # Ordinary strings and _RawNumber values are written unchanged.
        return str(value)
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return ""
    # Nested objects or arrays are not expected in a flat object.
    # If one appears, store it as compact JSON text.
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), default=str)


