        raise ValueError("JSON input must be a single object")

    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\r\n")
    writer.writerow([str(k) for k in data.keys()])
    writer.writerow([_cell(v) for v in data.values()])
