import base64
import binascii
import html
import re


def _decode(encoded):
    if isinstance(encoded, bytes):
        encoded = encoded.decode('ascii', errors='ignore')
    s = re.sub(r'\s+', '', encoded)
    s = s.replace('-', '+').replace('_', '/')
    s += '=' * (-len(s) % 4)
    try:
        raw = base64.b64decode(s)
    except (binascii.Error, ValueError):
        raw = base64.b64decode(s.rstrip('=') + '=' * (-len(s.rstrip('=')) % 4))
    return raw.decode('utf-8')


def _wrap_segment(words, line_length):
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= line_length:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return lines


def clean_and_wrap(encoded, line_length):
    text = _decode(encoded)
    text = html.unescape(text)
    text = re.sub(r' {2,}', ' ', text)
    text = text.strip(' ')
    if not text:
        return ''
    out_lines = []
    segments = text.split('\n')
    for seg in segments:
        words = [w for w in seg.split(' ') if w]
        if not words:
            out_lines.append('')
            continue
        out_lines.extend(_wrap_segment(words, line_length))
    return '\n'.join(out_lines)

