def base64_json_to_csv(raw_string):
    if isinstance(raw_string, str):
        raw_bytes = raw_string.strip().encode("ascii")
    else:
        raw_bytes = bytes(raw_string).strip()
    padding = (-len(raw_bytes)) % 4
    if padding:
        raw_bytes += b"=" * padding
    decoded = base64.b64decode(raw_bytes)
