            minute = int(tparts[1])
        except ValueError:
            continue
        times.append((hour, minute))
    if not times:
        return [], (0, 0)
    total = sum(h * 60 + m for h, m in times)
    avg = total // len(times)
    return times, (avg // 60, avg % 60)

