import hashlib
import hmac


def hash_or_verify_sha256(text, expected=None):
    """Return the SHA-256 hex digest of text, or verify it against expected.

    If expected is None, return the lowercase hex digest of text (UTF-8).
    Otherwise return True if expected equals that digest, else False.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if expected is not None and not isinstance(expected, str):
        raise TypeError("expected must be a string or None")

    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()

    if expected is None:
        return digest

    # Compare bytes in constant time. surrogatepass keeps lone surrogates in
    # expected from raising an error; such input simply won't match.
    return hmac.compare_digest(
        digest.encode("ascii"),
        expected.encode("utf-8", "surrogatepass"),
    )

