import hashlib
import hmac


def hash_or_verify_sha256(text, expected=None):
    """Return the SHA-256 hex digest of text, or verify it against expected.

    If expected is None, return the lowercase hex digest of the UTF-8 encoded
    text. Otherwise return True if expected exactly equals that digest and
    False if it does not. The comparison runs in constant time.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    if expected is not None and not isinstance(expected, str):
        raise TypeError("expected must be a str or None, got %s" % type(expected).__name__)

    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()

    if expected is None:
        return digest

    # Compare as bytes so non-ASCII input in expected does not raise an error.
    try:
        expected_bytes = expected.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return hmac.compare_digest(digest.encode("ascii"), expected_bytes)

