def underscore_target_phrases(target_phrases, sentences):
    # Lowercase the phrases, skip empty ones and drop duplicates.
    phrases = []
    seen = set()
    for p in target_phrases:
        lp = str(p).lower()
        if lp and lp not in seen:
            seen.add(lp)
            phrases.append(lp)

    result = []
    for sentence in sentences:
        s = str(sentence).lower()
        # Mark every character covered by an occurrence of any phrase.
        # Overlapping occurrences are included.
        marked = [False] * len(s)
        for p in phrases:
            if ' ' not in p:
                continue
            plen = len(p)
            start = s.find(p)
            while start != -1:
                for i in range(start, start + plen):
                    marked[i] = True
                start = s.find(p, start + 1)
        chars = [
            '_' if (c == ' ' and marked[i]) else c
            for i, c in enumerate(s)
        ]
        result.append(''.join(chars))
    return result

