import re


def underscore_target_phrases(target_phrases, sentences):
    phrases = []
    seen = set()
    for p in target_phrases:
        if p is None:
            continue
        lp = str(p).lower()
        if not lp or lp in seen:
            continue
        seen.add(lp)
        phrases.append(lp)

    lowered = [str(s).lower() for s in sentences]
    if not phrases:
        return lowered

    # Longest phrases first so longer matches win over their sub-phrases
    phrases.sort(key=len, reverse=True)
    pattern = re.compile('|'.join(re.escape(p) for p in phrases))

    def repl(m):
        return m.group(0).replace(' ', '_')

    return [pattern.sub(repl, s) for s in lowered]

