import binascii


def decode_hex_text(hex_string):
    """Decode a hex string into bytes, then decode those bytes as UTF-8.

    Invalid UTF-8 byte sequences are dropped. Raises ValueError if the input
    is not a valid hex string (odd length, non-hex characters, etc.).
    """
    if isinstance(hex_string, (bytes, bytearray)):
        try:
            hex_string = bytes(hex_string).decode('ascii')
        except UnicodeDecodeError:
            raise ValueError('Input is not a valid hex string')
    if not isinstance(hex_string, str):
        raise ValueError('Input must be a string of hexadecimal digits')
    if len(hex_string) % 2 != 0:
        raise ValueError('Hex string must have an even number of digits')
    if any(c not in '0123456789abcdefABCDEF' for c in hex_string):
        raise ValueError('Hex string contains non-hexadecimal characters')
    try:
        raw = binascii.unhexlify(hex_string)
    except (binascii.Error, TypeError) as exc:
        raise ValueError('Input is not a valid hex string: %s' % exc)
    return raw.decode('utf-8', errors='ignore')

