def most_common_url_value(records):
    entries = []  # list of [value, count] in order of first appearance
    index = {}    # hashable value -> position in entries
    unhashable_positions = []

    for record in records or []:
        if not isinstance(record, dict):
            continue
        for key, value in record.items():
            if not (isinstance(key, str) and (key.startswith("http://") or key.startswith("https://"))):
                continue
            try:
                hash(value)
                hashable = True
            except TypeError:
                hashable = False
            if hashable:
                pos = index.get(value)
                if pos is None:
                    index[value] = len(entries)
                    entries.append([value, 1])
                else:
                    entries[pos][1] += 1
            else:
                found = False
                for pos in unhashable_positions:
                    if entries[pos][0] == value:
                        entries[pos][1] += 1
                        found = True
                        break
                if not found:
                    unhashable_positions.append(len(entries))
                    entries.append([value, 1])

    if not entries:
        return {}

    best_value, best_count = entries[0]
    for value, count in entries[1:]:
        if count > best_count:
            best_value, best_count = value, count

    try:
        return {best_value: best_count}
    except TypeError:
        # Unhashable values cannot be dict keys; fall back to a string representation.
        return {repr(best_value): best_count}

