        files = {}
    result = []
    if not path:
        return result

    def add_component(comp):
        if comp == '':
            return
        if comp in files:
            result.append((comp, _digest(files[comp])))
        else:
            result.append((comp, None))

    if not delimiter:
        add_component(path)
        return result

    pieces = path.split(delimiter)
    for i, piece in enumerate(pieces):
        if i > 0:
            result.append((delimiter, None))
        add_component(piece)
    return result

