def _b64decode(encoded):
    if isinstance(encoded, str):
        data = encoded.strip().encode('ascii', errors='ignore')
    else:
        data = bytes(encoded).strip()
    # Remove internal whitespace and fix missing padding
    data = b''.join(data.split())
    missing = (-len(data)) % 4
    if missing:
        data += b'=' * missing
    try:
        return base64.b64decode(data)
    except (binascii.Error, ValueError):
        return base64.urlsafe_b64decode(data)


def clean_and_wrap(encoded, line_length):
    raw = _b64decode(encoded)
    text = raw.decode('utf-8', errors='replace')
    text = html.unescape(text)
    # Collapse all runs of whitespace (including non-breaking spaces) into single spaces
    text = ' '.join(text.split())
    if not text:
        return ''
    return textwrap.fill(text, width=line_length)

