import base64
import binascii
import html
import textwrap


def clean_and_wrap(encoded, line_length):
    """Decode base64 HTML-escaped UTF-8 text, unescape entities, normalize
    whitespace, and word-wrap to line_length characters per line."""
    if isinstance(encoded, str):
        data = encoded.encode('ascii', errors='ignore')
    else:
        data = bytes(encoded)
    # Remove any whitespace in the encoded input and fix missing padding.
    data = b''.join(data.split())
    missing = (-len(data)) % 4
    if missing:
        data += b'=' * missing
    try:
        raw = base64.b64decode(data)
    except (binascii.Error, ValueError):
        raw = base64.urlsafe_b64decode(data)

    text = raw.decode('utf-8', errors='replace')
    # Strip a leading BOM if present.
    if text.startswith('\ufeff'):
        text = text[1:]

    # Unescape HTML entities (repeat in case of double-escaping like &amp;amp;).
    for _ in range(5):
        unescaped = html.unescape(text)
        if unescaped == text:
            break
        text = unescaped

    # Collapse all runs of whitespace (including non-breaking spaces) to one space.
    text = ' '.join(text.split())
    if not text:
        return ''

    return textwrap.fill(text, width=line_length)

