import struct
import string

_HEX_DIGITS = frozenset(string.hexdigits)


def hex_to_float_utf8(hex_key):
    if isinstance(hex_key, (bytes, bytearray)):
        try:
            hex_key = bytes(hex_key).decode('ascii')
        except UnicodeDecodeError:
            raise ValueError('hex_key must contain only hexadecimal digits')
    if not isinstance(hex_key, str):
        raise ValueError('hex_key must be a string of 8 hexadecimal digits')
    if len(hex_key) != 8 or not all(c in _HEX_DIGITS for c in hex_key):
        raise ValueError('hex_key must be exactly 8 hexadecimal digits (4 bytes)')
    raw = bytes.fromhex(hex_key)
    if len(raw) != 4:
        raise ValueError('hex_key must encode exactly 4 bytes')
    (value,) = struct.unpack('>f', raw)
    return str(value).encode('utf-8')
